catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue === '') {
        return;
    }

    var venueValue = g_form.getValue('v_venue_name');
    var venueName = g_form.getDisplayValue('v_venue_name');

    if (!venueValue) {
        g_form.showFieldMsg('v_venue_name', 'Venue name is missing.', 'error');
        return;
    }

    var ga = new GlideAjax('VenueUtils');
    ga.addParam('sysparm_name', 'checkVenueAvailabilityByName');
    ga.addParam('venueName', venueName);

    ga.getXMLAnswer(function(response) {
        try {
            var result = JSON.parse(response);

            g_form.hideFieldMsg('v_venue_name', true);

            if (result.exists) {
                g_form.showFieldMsg('v_venue_name', result.msg || 'This venue is already booked. Please select another.', 'error');
            } else {
                g_form.showFieldMsg('v_venue_name', 'Venue is available.', 'info');
            }

        } catch (e) {
            g_form.showFieldMsg('v_venue_name', 'Error checking venue availability.', 'error');
        }
    });
}
